H.background();
const rho = 1000; // water kg/m^3
const A1 = 0.06, A2 = Math.max(0.01, P.A2); // throat area slider, m^2
const Q = P.Q; // m^3/s
const g = 9.8;
const h2 = P.h2; // height of throat relative to inlet, m
const v1 = Q / A1, v2 = Q / A2;
// Bernoulli: P1 + 0.5 rho v1^2 + rho g h1 = P2 + 0.5 rho v2^2 + rho g h2
const h1 = 0, P1 = 120000; // Pa gauge at inlet
const P2 = P1 + 0.5*rho*v1*v1 + rho*g*h1 - 0.5*rho*v2*v2 - rho*g*h2;
H.text("Bernoulli: P + 1/2 rho v^2 + rho g h = const", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Faster/higher flow -> lower pressure (energy per volume conserved)", 24, 52, { color: H.colors.sub, size: 13 });
const cy1 = 360, xJoin = 430;
const cy2 = cy1 - h2*40; // higher throat drawn higher
const sc = 600;
const r1 = Math.min(80, A1*sc), r2 = Math.min(80, A2*sc);
// pipe walls
H.path([[80, cy1-r1],[xJoin, cy1-r1],[xJoin+10, cy2-r2],[820, cy2-r2]], { color: H.colors.sub, width: 3 });
H.path([[80, cy1+r1],[xJoin, cy1+r1],[xJoin+10, cy2+r2],[820, cy2+r2]], { color: H.colors.sub, width: 3 });
// moving particle
const ph = (t*0.5)%1;
const px = 80 + ph*740;
const inThroat = px > xJoin;
const py = (inThroat ? cy2 : cy1) + 6*Math.sin(t*3);
H.circle(px, py, 6, { fill: inThroat ? H.colors.warn : H.colors.accent2 });
// pressure bars
H.rect(120, 470, 40, -Math.max(2,P1/3000), { fill: H.colors.accent2 });
H.rect(640, 470, 40, -Math.max(2,P2/3000), { fill: H.colors.warn });
H.text("inlet", 118, 488, { color: H.colors.sub, size: 11 });
H.text("throat", 636, 488, { color: H.colors.sub, size: 11 });
H.text("v1 = " + v1.toFixed(2) + " m/s   P1 = " + (P1/1000).toFixed(1) + " kPa", 24, 78, { color: H.colors.accent2, size: 13 });
H.text("v2 = " + v2.toFixed(2) + " m/s   P2 = " + (P2/1000).toFixed(1) + " kPa", 24, 96, { color: H.colors.warn, size: 13 });
H.text("throat A2 = " + A2.toFixed(3) + " m^2, h2 = " + h2.toFixed(1) + " m", 24, 114, { color: H.colors.sub, size: 12 });
